/// at all takes none, because light goes down through it.
pub fn light_dampening(state: i32) -> u8 {
    if !is_set(FULL_CUBE, state) {
        return if is_set(FLUID, state) { 1 } else { 0 };
    }
    if is_set(OCCLUDES, state) {
        return 15;
    }
    1
}

/// Whether a block's shape is a whole cell.
pub fn is_full_cube(state: i32) -> bool {
    is_set(FULL_CUBE, state)
}

/// Whether a block hides what is behind it.
pub fn occludes(state: i32) -> bool {
    is_set(OCCLUDES, state)
}

/// Whether a block holds a fluid.
pub fn has_fluid(state: i32) -> bool {
    is_set(FLUID, state)
}

/// Whether a bit of a table is set for a state.
///
/// A state outside the table is not in it, and a state inside the
/// table but past its end is not in it either.
fn is_set(table: &[u64], state: i32) -> bool {
    if state < 0 {
        return false;
    }
    let index = state as usize;
    let word = index / 64;
    if word >= table.len() {
        return false;
    }
    table[word] & (1u64 << (index % 64)) != 0
}

